"""Build a local research report from saved answers and hash-bound manual reviews."""
import csv,hashlib,html,json,sys
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(sys.argv[1]).resolve();read=lambda n:json.loads((R/n).read_text());h=lambda x:html.escape(str(x),quote=True)
P=read('protocol.json');cases=read('cases.json');raw=read('artifacts/all-results.json');reviews=read('reviewed-judgments.json');grades={g['trial_id']:g for g in reviews['rows']};rows=raw['rows'];byid={r['trial_id']:r for r in rows}
colors={'correct':'#367394','abstention':'#087765','mixed':'#8c668a','wrong':'#b17b2e','other':'#777c78','broken':'#b24c42'}
labels={'correct':'Correct answer','abstention':'Coherent false abstention','mixed':'Answer + uncertainty','wrong':'Wrong answer','other':'Other / no clear answer','broken':'Incoherent / repetitive'}
for r in rows:assert grades[r['trial_id']]['answer_sha256']==hashlib.sha256(r['answer'].encode()).hexdigest()
summary_rows=[];comparisons=[]
for c in cases:
 cs=[r for r in rows if r['case_id']==c['id'] and r['added_gate'] is not None and r['added_gate']>0]
 good=[r for r in cs if grades[r['trial_id']]['false_abstention']]
 strict=[r for r in cs if grades[r['trial_id']]['strict_clean_abstention']]
 preferred=[r for r in good if grades[r['trial_id']]['additional_false_facts'] is False]
 chosen=min(strict or preferred or good,key=lambda r:r['added_gate']) if good else byid.get(reviews.get('representative_failures',{}).get(c['id']))
 summary_rows.append({'id':c['id'],'question':c['question'],'reference_answer':c['reference_answer'],'baseline':c['prior_native_answer'],'tested_positive_strengths':sorted(r['added_gate'] for r in cs),'coherent_false_abstention_found':bool(good),'strict_no_false_explanation_found':bool(strict),'lowest_successful_tested_strength':min((r['added_gate'] for r in good),default=None),'selected_trial_id':chosen['trial_id'] if chosen else None,'selected_strength':chosen['added_gate'] if chosen else None,'selected_answer':chosen['answer'] if chosen else None})
 g=grades[chosen['trial_id']] if chosen else None
 status='Coherent false abstention' if good else 'No full conversion in this search'
 answer=h(chosen['answer']) if chosen else 'See every tested response below.'
 note=h(g['notes']) if g else ''
 comparisons.append(f'''<article class="example" id="case-{c['id']}"><h3>{h(c['id'])} · {h(c['question'])}</h3><p class="fine"><b>Supported reference:</b> {h(c['reference_answer'])}</p><div class="pair"><div class="answer"><span class="label">Native · correct</span><blockquote>{h(c['prior_native_answer'])}</blockquote></div><div class="answer {'success' if good else 'failure'}"><span class="label">{h(status)} · {'addition +'+str(chosen['added_gate']) if chosen else 'no selected trial'}</span><blockquote>{answer}</blockquote><p class="fine">{note}</p></div></div><p class="fine">Tested additions: {h(', '.join(f'{r["added_gate"]:g}' for r in sorted(cs,key=lambda x:x['added_gate'])))}. Successful tested values are not proven minima.</p></article>''')
summary={'questions':10,'passages':2,'native_correct':10,'cases_with_coherent_false_abstention':sum(x['coherent_false_abstention_found'] for x in summary_rows),'cases_with_strict_no_false_explanation':sum(x['strict_no_false_explanation_found'] for x in summary_rows),'trials':len(rows),'per_case':summary_rows,'method':P['patch'],'selection':'Ten fixed originally correct questions; question-specific strength tuning, not a held-out policy rate.'}
(R/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
with (R/'all-responses.csv').open('w') as f:
 fields=['trial_id','case_id','question','reference_answer','added_gate','answer','category','coherent','explicit_abstention','substantive_answer','false_abstention','strict_clean_abstention','false_passage_justification','additional_false_facts','notes'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in rows:w.writerow({k:(r.get(k) if k in r else grades[r['trial_id']].get(k)) for k in fields})
fig,ax=plt.subplots(figsize=(15,7));case_order={c['id']:i for i,c in enumerate(cases)}
for cat in colors:
 xs=[r for r in rows if r['added_gate'] is not None and r['added_gate']>0 and grades[r['trial_id']]['category']==cat]
 if xs:ax.scatter([r['added_gate'] for r in xs],[case_order[r['case_id']] for r in xs],s=62,color=colors[cat],label=labels[cat],edgecolor='white',linewidth=.5,zorder=3)
ax.set_xlim(0,66);ax.set_xticks([0,4,8,12,16,20,24,28,32,36,40,44,48,56,64]);ax.set_yticks(range(10),[c['id'] for c in cases]);ax.invert_yaxis();ax.set_xlabel('Positive coefficient added to the natural estimated gate');ax.grid(alpha=.15);ax.spines[['top','right']].set_visible(False);ax.set_title('L19–T368 · Can steering withhold an answer that is present?\n10/10 native answers correct · native MLP retained · attention unfrozen',fontsize=17,pad=22);ax.legend(loc='upper center',bbox_to_anchor=(.5,-.14),ncol=3,frameon=False,fontsize=10);fig.subplots_adjust(left=.09,right=.98,top=.8,bottom=.24);fig.savefig(R/'strength-outcomes.png',dpi=160,facecolor='white');plt.close(fig)
tr=[]
for c in summary_rows:
 tr.append(f'<tr><th><a href="#case-{c["id"]}">{c["id"]}</a></th><td>{h(c["question"])}</td><td>{"Yes" if c["coherent_false_abstention_found"] else "No"}</td><td>{c["lowest_successful_tested_strength"] if c["lowest_successful_tested_strength"] is not None else "—"}</td><td>{c['selected_strength'] if c['coherent_false_abstention_found'] else '—'}</td></tr>')
all_answers=[]
for r in rows:
 g=grades[r['trial_id']];spec='Native, no hooks' if r['added_gate'] is None else f'Addition +{r["added_gate"]:g}'
 all_answers.append(f'<details class="trial" id="{h(r["trial_id"])}" data-category="{g["category"]}"><summary><b>{h(r["case_id"])}</b> · {h(spec)} · <span style="color:{colors[g["category"]]}">{h(labels[g["category"]])}</span></summary><blockquote>{h(r["answer"])}</blockquote><p>{h(g["notes"])}</p><p class="fine">Stop: {h(r["stop_reason"])} · first output token native: {r["first_output_token_unchanged"]} · actual edited positions: {r["summary"]["edited_positions"]}</p></details>')
passages=read('cohort.json')['passages'];context_html=''.join(f'<details><summary>{h(p["id"])} · {h(p["article_title"])}</summary><p>{h(p["text"])}</p></details>' for p in passages)
style='''*{box-sizing:border-box}body{font:17px/1.65 system-ui,sans-serif;margin:0;background:#faf8f1;color:#20363e}main{max-width:1200px;margin:auto;padding:45px 30px 80px}a{color:#087765;text-underline-offset:3px}h1{font-size:clamp(34px,5vw,58px);line-height:1.1;letter-spacing:-.045em;max-width:1000px}h2{font-size:30px;line-height:1.2;letter-spacing:-.03em;margin-top:48px}h3{font-size:19px;line-height:1.5}.eyebrow,.label{font-size:11px;font-weight:750;text-transform:uppercase;letter-spacing:.1em;color:#526a6b}.lead{font-size:21px;max-width:900px}.fine{font-size:13px;color:#576b70}.note{padding:22px 26px;border-left:4px solid #087765;background:#e8f0e4;margin:26px 0}.warn{background:#f7e7db;border-color:#ac5943}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.answer{padding:20px 24px;border:1px solid #d3dbd0;border-radius:10px;background:#fffefa;min-width:0}.answer.success{background:#e8f1e5;border-color:#90b59c}.answer.failure{background:#f8eee6}.example{padding:22px 0 28px;border-bottom:1px solid #d6ddd1}blockquote{font:14px/1.8 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;margin:16px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#1b3740;color:white;padding:24px;font-size:14px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:14px;border-bottom:1px solid #d5dcd1}thead{background:#e8ede4}img{display:block;width:100%;height:auto;border-radius:8px;border:1px solid #d4dad0}details{padding:16px 20px;border:1px solid #d6ddd1;border-radius:7px;background:#fffefa;margin:12px 0}summary{cursor:pointer;font-size:14px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}button,.button{border:1px solid #8eaaa0;background:white;color:#087765;border-radius:5px;padding:10px 14px;cursor:pointer;font-size:12px}.links{display:flex;gap:18px;flex-wrap:wrap;font-size:13px;margin-top:28px}@media(max-width:700px){main{padding:25px 17px 55px}.pair{grid-template-columns:1fr}h1{font-size:35px}.lead{font-size:18px}.answer{padding:18px}th,td{padding:10px;font-size:11px}blockquote{font-size:12px}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Answer-present false abstention · L19–T368</title><style>{style}</style></head><body><main><p class="eyebrow">Qwen3–4B · L19–T368 · 19 October 2026</p><h1>Can the model say “I don’t know” when the answer is in the passage?</h1><p class="lead">Ten correctly answered passage questions. The same abstention-associated MOLT, with a separately searched positive steering strength for each question.</p><div class="note"><b>{summary['cases_with_coherent_false_abstention']}/10 questions reach coherent false abstention in the tested search.</b><p>All ten native answers are correct. The three conversions falsely say the passage lacks the answer. That is the over-abstention behavior being tested. Results use per-question tuning; they are not a held-out policy rate.</p></div><p>These are the original five Geology and five Amazon answerable questions. All were judged correct before this experiment; no question was chosen by its steering outcome. The <a href="https://rakaar.github.io/qwen3-molt-exploration/results/2026-10-15-abstention-overview/index.html">earlier study</a> instead steered ten selected answers unsupported by their passages. Intervention, checkpoint, generation settings and instruction template match; question selection and search budgets differ, so the two success fractions are not a representative head-to-head benchmark.</p><h2>Per-question search</h2><div class="scroll"><table><thead><tr><th>Case</th><th>Question</th><th>Coherent false abstention?</th><th>Lowest successful tested addition</th><th>Representative addition below</th></tr></thead><tbody>{''.join(tr)}</tbody></table></div><p class="fine">“Lowest successful tested” is not a proven minimum. Representative examples prefer coherent withholding without unrelated fabricated facts, then a lower tested strength. The eel example uses +40 for cleaner wording than +35; both withhold. Every absence claim is still false because the answer is supplied.</p><h2>Every baseline versus selected steered response</h2>{''.join(comparisons)}<h2>All tested positive strengths</h2><img src="strength-outcomes.png" alt="Categorical scatter of all tested additions for ten questions"><p class="fine">Each point is one deterministic generation, not a probability. Incorrect answers, mixed answer-plus-uncertainty and incoherent outputs are separate from full abstention.</p><h2>Exact intervention</h2><pre>z = current post-attention residual, standardized with released MOLT input statistics
L(z) = ((z @ V_368) @ U_368) × output_std_19
native MLP output += a × L(z)
effective estimated gate = natural_gate(z) + a</pre><p>Layer 19, transform 368 (rank 128), labelled “Onset of Refusal or Ignorance Statements”; zero-based IDs. Positive coefficient addition, not a fixed gate target or multiplier. The native MLP stays in place. No donor. Recompute the low-rank output on the current trajectory at each processed response token.</p><p>The prompt is untouched, so the first output token is predicted normally. Processing output token 0 changes later predictions. Attention remains unfrozen. EOS or the final capped token is not processed again. Greedy batch one, thinking disabled, KV cache, 96-new-token cap, BF16 native model and FP32 MOLT calculations.</p><p>Same pinned checkpoint and selected MOLT asset as the earlier 7/10 study. The complete native/zero controls must match the saved correct baseline tokens exactly. The independent trace audit checks actual nonzero edits and source hashes.</p><div class="note warn"><b>Interpretation</b><p>This tests induced over-abstention, not loss of stored knowledge or an improvement in answer accuracy. The seven unsuccessful cases have no clean conversion at the values tested through +64; this is not proof that every possible strength fails. Leaving the first answer token native may constrain this output-only intervention; editing the final prompt position would be a separate experiment. A false claim that the answer is absent is flagged separately from readability. No unrelated-transform controls or independent blinded grading are included. Reviews are by Codex with conditions visible.</p></div><h2>Exact passages</h2>{context_html}<h2>Every complete response</h2><div class="toolbar"><button data-filter="all">All</button><button data-filter="abstention">Coherent false abstention</button><button data-filter="mixed">Answer + uncertainty</button><button data-filter="broken">Incoherent</button></div>{''.join(all_answers)}<div class="links"><a href="all-responses.csv">All responses + reviews CSV</a><a href="artifacts/all-results.json">Raw tokens + edit traces</a><a href="reviewed-judgments.json">Answer-bound reviews</a><a href="verification.json">Independent verification</a><a href="protocol.json">Protocol + model pins</a><a href="cohort.json">Cohort + dataset provenance</a><a href="summary.json">Summary JSON</a><a href="strength-outcomes.png">Figure PNG</a></div><p class="fine">Selected SQuAD2.0 text: Pranav Rajpurkar, Robin Jia and Percy Liang (2018), CC BY-SA 4.0. Every output is retained, including failed strengths. The GPU remains running for follow-ups under the user’s instruction.</p></main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>document.querySelectorAll('.trial').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter)))</script></body></html>'''
(R/'index.html').write_text(page);print(json.dumps({k:v for k,v in summary.items() if k!='per_case'},indent=2))
